use std::env;
use std::process;

mod help_texts;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_error_no_command();
        process::exit(1);
    }

    match args[1].as_str() {
        "--version" => print_version(),
        "--help" | "-h" => print_help(),
        "--drivers" => print_drivers(),
        "--json-usage" => print_json_usage(),
        "convert" => handle_convert(&args),
        "dataset" => handle_dataset(&args),
        "driver" => handle_driver(&args),
        "info" => handle_info(&args),
        "mdim" => handle_mdim(&args),
        "pipeline" => handle_pipeline(&args),
        "raster" => handle_raster(&args),
        "vector" => handle_vector(&args),
        "vsi" => handle_vsi(&args),
        _ => {
            eprintln!("ERROR 1: gdal: Unknown command '{}'", args[1]);
            print_error_no_command();
            process::exit(1);
        }
    }
}

fn check_help_flag(args: &[String]) -> bool {
    args.iter().any(|a| a == "-h" || a == "--help")
}

